package com.aquagrow.api.dto;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Request for the MCP-powered AI chat endpoint.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class McpChatRequest {
    /** The user's message */
    private String message;
    /** Unique session ID for conversation memory (e.g. UUID generated by the frontend) */
    private String conversationId;
}
